export function decorateListingPreview(text:string){const used=new Set<string>();let fallbackIndex=0;const nextFallback=()=>{while(fallbackIndex<FALLBACK_EMOJIS.length&&used.has(FALLBACK_EMOJIS[fallbackIndex]))fallbackIndex++;return FALLBACK_EMOJIS[fallbackIndex++]||'🔘';};return String(text||'').split('\n').map(line=>{const match=line.match(/^(?:(\S+)\s+)?<b>([^<]+):<\/b>(.*)$/);if(!match)return line;const existingOuter=match[1]||'';let label=match[2].trim(),embedded='';for(const emoji of EMBEDDED_LABEL_EMOJIS){if(label.startsWith(`${emoji} `)){embedded=emoji;label=label.slice(emoji.length).trim();break;}}let emoji=PREVIEW_EMOJIS[label]||existingOuter||embedded;if(!emoji||used.has(emoji))emoji=nextFallback();used.add(emoji);return `${emoji} <b>${label}:</b>${match[3]}`;}).join('\n');}
