    (typeof v === 'string' && !!v.trim() && !/^(?:[-–—]|n\/?a|null|undefined|NO_INFORMATION|NOT_SPECIFIED|UNKNOWN|nicht (?:vorhanden|angegeben)|keine Angabe|auf Anfrage)$/i.test(v.trim()));
