    const propertyType = text.match(/\b(Studio|Wohnung|Apartment|Maisonette|Penthouse|Loft|Dachgeschosswohnung|Erdgeschosswohnung)\s+zur Miete\b/i)?.[1];
    if (!out.property_type && propertyType) out.property_type = propertyType;
    const locationSection = text.match(/\bLage\b([\s\S]*?)(?=\bWeitere Services\b|$)/i)?.[1] || '';
    const location = locationSection.match(/([A-ZÄÖÜ][A-Za-zÄÖÜäöüß0-9 .,'’\/-]{1,80}?)\s*\((2\d{4})\)/);
    if (!out.address && location) out.address = `${location[1].trim()} (${location[2]})`;
  }
  const address=clean.match(/<([a-z][a-z0-9]*)\b[^>]*id=["']viewad-locality["'][^>]*>([\s\S]*?)<\/\1>/i);
  if(address && /kleinanzeigen\.de/.test(hostname))out.address=decode(address[2]);
  for(const m of clean.matchAll(/<(?:img|meta|div)\b[^>]*>/gi)) {
    const tag=m[0], attr=(name:string)=>tag.match(new RegExp(`(?:^|\\s)${name}\\s*=\\s*["']([^"']+)["']`,'i'))?.[1];
    // Only listing gallery/itemprop images and the page's explicit preview image.
    if(attr('property')==='og:image') {const u=imageUrl(attr('content'),base);if(u)out.images.push(u);}
    else if((/(^|\.)kleinanzeigen\.de$/.test(hostname)&&attr('data-imgsrc')) || attr('itemprop')==='image' || /(?:gallery|imagebox|expose-picture|listing-image)/i.test(attr('class')||'')) {
      const u=imageUrl(attr('data-imgsrc')||attr('data-src')||attr('data-original')||attr('src'),base);if(u)out.images.push(u);
    }
  }
  out.images=collectImages({images:out.images},base);
  return out;
}

export async function waitForDispatchSlot(db: any, owner: string, deadline: number, clock = Date.now, sleep = (ms: number) => new Promise(r => setTimeout(r, ms))) {
  const {data,error} = await db.rpc('dispatcher_slot',{p_owner:owner});
  if(error) throw error;
  const at = new Date(data).getTime();
  if(!Number.isFinite(at)) throw new Error('Invalid dispatcher slot');
  if(at>=deadline) return false;
  const wait=Math.max(0,at-clock());
  if(wait) await sleep(wait);
  return clock()<deadline;
}

type Lease = { id: string; attempt: number; claimedAt: string };

export async function claimDelivery(
  db: any,
  event: any,
): Promise<Lease | null> {
  const lease = {
    id: event.id,
    attempt: Number(event.dispatch_attempts || 0) + 1,
    claimedAt: new Date().toISOString(),
  };
  const { data, error } = await db
    .from("delivery_events")
    .update({
      status: "processing",
      dispatch_attempts: lease.attempt,
      last_attempt_at: lease.claimedAt,
    })
    .eq("id", event.id)
    .eq("status", event.status)
    .eq("dispatch_attempts", Number(event.dispatch_attempts || 0))
    .select("id")
    .maybeSingle();
  if (error) throw error;
  return data ? lease : null;
}

export async function finishDelivery(
  db: any,
  lease: Lease,
  patch: Record<string, unknown>,
) {
  const { data, error } = await db
    .from("delivery_events")
    .update(patch)
    .eq("id", lease.id)
    .eq("status", "processing")
    .eq("dispatch_attempts", lease.attempt)
    .eq("last_attempt_at", lease.claimedAt)
    .select("id")
    .maybeSingle();
  if (error) throw error;
  if (!data) throw new Error(`Delivery ${lease.id}: lease no longer owned`);
}

export async function recoverDeliveries(db: any) {
  // Longer than the hosted Edge Function lifetime. Never steal a live request.
  const { error } = await db
    .from("delivery_events")
    .update({
      status: "failed",
      delivery_outcome_unknown: true,
      next_retry_at: new Date().toISOString(),
      error_message:
        "Expired delivery lease; prior Telegram outcome may be unknown",
    })
    .eq("status", "processing")
    .lt("last_attempt_at", new Date(Date.now() - 600_000).toISOString());
  if (error) throw error;
}
